-- Generated by scripts/theme.sh from theme/palette.sh. Do not edit.
-- swayimg configuration. Colours are 0xAARRGGBB.

swayimg.text.font = "JetBrains Mono"
swayimg.text.size = 16
swayimg.text.color = 0xff${FG_HEX}
swayimg.text.background = 0xcc${BG_HEX}
swayimg.text.shadow = 0x00000000

swayimg.viewer.set_window_background(0xff${BG_HEX})
swayimg.viewer.mark_color = 0xff${ACCENT_HEX}

swayimg.gallery.window_color = 0xff${BG_HEX}
swayimg.gallery.unselected_color = 0xff${BG_HEX}
swayimg.gallery.selected_color = 0xff${BG_ALT_HEX}
swayimg.gallery.border_color = 0xff${ACCENT_HEX}

-- Do not watch the files: rotating an image replaces its file, and the
-- watcher would then drop it from the list and show the next image.
swayimg.imagelist.fsmon = false

-- Quote a path for /bin/sh
local function quote(path)
  return "'" .. path:gsub("'", "'\\''") .. "'"
end

-- Run a shell command with the path of the current image appended
local function run_on_image(command)
  local image = swayimg.viewer.get_image()
  if image then
    os.execute(command .. " " .. quote(image.path))
  end
  return image
end

-- Rotate the image file on disk and show the result
local function rotate(degrees)
  if run_on_image("mogrify -rotate " .. degrees) then
    swayimg.viewer.reload()
  end
end

-- Key bindings carried over from the nsxiv key handler
swayimg.viewer.on_key("Ctrl+c", function()
  local image = swayimg.viewer.get_image()
  if image then
    os.execute("clip image/png < " .. quote(image.path))
  end
end)
swayimg.viewer.on_key("Ctrl+w", function() run_on_image("set-wallpaper") end)
swayimg.viewer.on_key("Ctrl+comma", function() rotate(270) end)
swayimg.viewer.on_key("Ctrl+period", function() rotate(90) end)
swayimg.viewer.on_key("Ctrl+slash", function() rotate(180) end)
-- Delete the file from disk and remove it from the list
swayimg.viewer.on_key("Shift+Delete", function()
  local image = run_on_image("rm --")
  if image then
    swayimg.imagelist.remove(image.path)
  end
end)
